diff --git a/source/standalone/live-client-request.ts b/source/standalone/live-client-request.ts
new file mode 100644
index 0000000..3563c1d
--- /dev/null
+++ b/source/standalone/live-client-request.ts
@@ -0,0 +1,8 @@
+import type {Writable, Readable} from 'node:stream';
+import type {ClientRequest} from 'node:http';
+
+export function isLiveClientRequest(clientRequest: Writable | Readable): clientRequest is ClientRequest {
+	return (clientRequest as Writable).writable && !(clientRequest as Writable).writableEnded && !clientRequest.destroyed;
+}
+
+export default isLiveClientRequest;
diff --git a/test/live-client-request.ts b/test/live-client-request.ts
new file mode 100644
index 0000000..e6ff7d5
--- /dev/null
+++ b/test/live-client-request.ts
@@ -0,0 +1,59 @@
+import type {Writable} from 'node:stream';
+import test from 'ava';
+import {isLiveClientRequest} from '../source/standalone/live-client-request.js';
+
+test('requires a writable request that has not ended or been destroyed', t => {
+	t.true(isLiveClientRequest({writable: true, writableEnded: false, destroyed: false} as Writable));
+	t.true(isLiveClientRequest({writable: true} as Writable));
+	t.false(isLiveClientRequest({writable: true, writableEnded: false, destroyed: true} as Writable));
+});
+
+test('checks stream flags in order and short-circuits', t => {
+	const reads: string[] = [];
+	let writable = false;
+	let writableEnded = true;
+	const request = {
+		get writable() {
+			reads.push('writable');
+			return writable;
+		},
+		get writableEnded() {
+			reads.push('writableEnded');
+			return writableEnded;
+		},
+		get destroyed() {
+			reads.push('destroyed');
+			return false;
+		},
+	};
+
+	t.false(isLiveClientRequest(request as Writable));
+	t.deepEqual(reads.splice(0), ['writable']);
+
+	writable = true;
+	t.false(isLiveClientRequest(request as Writable));
+	t.deepEqual(reads.splice(0), ['writable', 'writableEnded']);
+
+	writableEnded = false;
+	t.true(isLiveClientRequest(request as Writable));
+	t.deepEqual(reads, ['writable', 'writableEnded', 'destroyed']);
+});
+
+test('preserves empty-input behavior', t => {
+	t.is<boolean | undefined, undefined>(isLiveClientRequest({} as Writable), undefined);
+	t.throws(() => isLiveClientRequest(undefined as unknown as Writable), {instanceOf: TypeError});
+	t.throws(() => isLiveClientRequest(null as unknown as Writable), {instanceOf: TypeError});
+});
+
+test('propagates errors from the earlier checks even on destroyed requests', t => {
+	const error = new Error('Cannot read writableEnded');
+	const request = {
+		writable: true,
+		get writableEnded(): boolean {
+			throw error;
+		},
+		destroyed: true,
+	};
+
+	t.is(t.throws(() => isLiveClientRequest(request as Writable)), error);
+});
